package com.j256.ormlite.logger;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class LoggerFactory_setLogBackendType_0_0_Test {

    private LogBackendType mockLogBackendType;

    @BeforeEach
    public void setUp() {
        mockLogBackendType = mock(LogBackendType.class);
    }

    @Test
    public void testSetLogBackendTypeAvailable() {
        when(mockLogBackendType.isAvailable()).thenReturn(true);
        LoggerFactory.setLogBackendType(mockLogBackendType);
        assertNotNull(LoggerFactory.getLogBackendFactory());
    }

    @Test
    public void testSetLogBackendTypeNotAvailable() {
        when(mockLogBackendType.isAvailable()).thenReturn(false);
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            LoggerFactory.setLogBackendType(mockLogBackendType);
        });
        assertEquals("Logging backend type " + mockLogBackendType + " is not available on the classpath", exception.getMessage());
    }
}
